import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.qcK96eCy.js";var i=JSON.parse(`{"title":"Production Database","description":"","frontmatter":{},"headers":[],"relativePath":"deployment/production-database.md","filePath":"deployment/production-database.md","lastUpdated":1786751537000}`),a={name:`deployment/production-database.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<div style="display:none;" hidden data-nosnippet>Are you an LLM? You can read better optimized documentation at /deployment/production-database.md for this page in Markdown format</div><h1 id="production-database" tabindex="-1">Production Database <a class="header-anchor" href="#production-database" aria-label="Permalink to “Production Database”">​</a></h1><p>The production database runs on <a href="https://neon.tech/" target="_blank" rel="noreferrer">Neon PostgreSQL</a> with <a href="https://developers.cloudflare.com/hyperdrive/" target="_blank" rel="noreferrer">Cloudflare Hyperdrive</a> providing connection pooling at the edge.</p><h2 id="neon-setup" tabindex="-1">Neon Setup <a class="header-anchor" href="#neon-setup" aria-label="Permalink to “Neon Setup”">​</a></h2><ol><li>Create a Neon project at <a href="https://console.neon.tech/" target="_blank" rel="noreferrer">console.neon.tech</a> (or via <a href="https://get.neon.com/HD157BR" target="_blank" rel="noreferrer">referral</a>)</li><li>Create separate databases for staging and production (or use Neon branching)</li><li>Copy the connection strings – you&#39;ll need them for Hyperdrive and migrations</li></ol><p>The connection string format: <code>postgresql://user:pass@host/dbname?sslmode=require</code></p><h2 id="hyperdrive-configuration" tabindex="-1">Hyperdrive Configuration <a class="header-anchor" href="#hyperdrive-configuration" aria-label="Permalink to “Hyperdrive Configuration”">​</a></h2><p>Hyperdrive is provisioned via Terraform. The module in <code>infra/modules/cloudflare/</code> splits the connection string into the fields Hyperdrive stores, and creates two configurations per environment:</p><div class="language-bash"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;"># Provision Hyperdrive for staging</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> infra:staging</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apply</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Binding</th><th>Caching</th><th>Use for</th></tr></thead><tbody><tr><td><code>HYPERDRIVE_CACHED</code></td><td>60s, 15s stale</td><td>Reads that tolerate being briefly stale</td></tr><tr><td><code>HYPERDRIVE_UNCACHED</code></td><td>Disabled</td><td>Writes, and reads that must not be stale (auth, billing)</td></tr></tbody></table><p>Terraform sets both values explicitly rather than inheriting them, so the window above is the reviewable source – see <a href="/specs/infra-terraform">Infrastructure</a>. A cached result can therefore be 75 seconds old, and a write never invalidates it: read-after-write, session, and permission checks belong on <code>HYPERDRIVE_UNCACHED</code>.</p><p>Give Hyperdrive Neon&#39;s <strong>unpooled</strong> connection string – the host without <code>-pooler</code>. Hyperdrive is itself the pool; Neon&#39;s runs in transaction mode, which breaks the prepared statements Hyperdrive caches on, and adds a second layer competing for the same connection budget. Both configurations open up to <code>origin_connection_limit</code> connections each, so the database must allow at least twice that.</p><p>Then copy the IDs into <code>apps/api/wrangler.jsonc</code> for the matching environment:</p><div class="language-bash"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> infra:staging</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> output</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -raw</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> wrangler_hyperdrive_bindings</span></span></code></pre></div><p>See <a href="/database/#connection-architecture">Database: Connection Architecture</a> for how these bindings are used in application code.</p><h2 id="running-migrations" tabindex="-1">Running Migrations <a class="header-anchor" href="#running-migrations" aria-label="Permalink to “Running Migrations”">​</a></h2><p>Migrations run directly against Neon (not through Hyperdrive). The <code>db/</code> workspace provides environment-specific commands:</p><div class="language-bash"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;"># Staging</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> db:migrate:staging</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;"># Production</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> db:migrate:production</span></span></code></pre></div><p>Each command reads only its own file – <code>.env.staging.local</code> or <code>.env.production.local</code> – and fails if that file is missing or does not define <code>DATABASE_URL</code>, rather than falling back to another environment&#39;s connection string. See <a href="/database/migrations">Database: Migrations</a> for the full workflow.</p><div class="warning custom-block"><p class="custom-block-title custom-block-title-default">WARNING</p><p>Review the SQL in <code>db/migrations/</code> before applying it to production. Those files are generated during development with <code>bun db:generate</code> and committed, so the exact statements are visible in the pull request that introduced them.</p></div><h2 id="database-performance" tabindex="-1">Database Performance <a class="header-anchor" href="#database-performance" aria-label="Permalink to “Database Performance”">​</a></h2><p>Neon suspends idle compute after a period of inactivity, so the first request after a quiet spell pays a cold start. Expect it on staging and on low-traffic production deployments before attributing the latency to Hyperdrive or the worker.</p><p>The shipped tables already index <code>organizationId</code> on <code>member</code> and <code>invitation</code>. Do the same on your own tenant-scoped tables: every scoped query filters on that column, so a missing index there costs more than anywhere else in the schema.</p>`,23)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};